"""PayPal Subscriptions calls through PayPal's official Server SDK (generated by APIMatic).

Every plan / subscription call PlanLab makes goes through `paypalserversdk`'s typed
SubscriptionsController: request bodies are built as SDK models from our dicts, so a field
the SDK does not know is dropped before it reaches PayPal. Webhook signature verification is
not in the SDK, so `paypal_client` still handles that one call over plain HTTP.

`execute(request)` is the executor the Save Agent and the rollout use: it takes the
`{method, path, body}` dict they log in the audit trail and dispatches it to the SDK.
"""
from __future__ import annotations

import json
import re
import uuid
from functools import lru_cache

from paypalserversdk.api_helper import APIHelper
from paypalserversdk.configuration import Environment
from paypalserversdk.exceptions.api_exception import ApiException
from paypalserversdk.http.auth.o_auth_2 import ClientCredentialsAuthCredentials
from paypalserversdk.models.activate_subscription_request import ActivateSubscriptionRequest
from paypalserversdk.models.cancel_subscription_request import CancelSubscriptionRequest
from paypalserversdk.models.create_subscription_request import CreateSubscriptionRequest
from paypalserversdk.models.modify_subscription_request import ModifySubscriptionRequest
from paypalserversdk.models.plan_request import PlanRequest
from paypalserversdk.models.suspend_subscription import SuspendSubscription
from paypalserversdk.models.update_pricing_schemes_request import UpdatePricingSchemesRequest
from paypalserversdk.paypal_serversdk_client import PaypalServersdkClient

from app import config
from app.paypal_client import PayPalError

SDK_NAME = "paypal-server-sdk (APIMatic-generated)"


@lru_cache(maxsize=1)
def _client() -> PaypalServersdkClient:
    if not config.PAYPAL_CLIENT_ID or not config.PAYPAL_CLIENT_SECRET:
        raise PayPalError(0, "PAYPAL_CLIENT_ID / PAYPAL_CLIENT_SECRET missing in .env")
    env = Environment.PRODUCTION if config.PAYPAL_ENV == "live" else Environment.SANDBOX
    return PaypalServersdkClient(
        client_credentials_auth_credentials=ClientCredentialsAuthCredentials(
            o_auth_client_id=config.PAYPAL_CLIENT_ID,
            o_auth_client_secret=config.PAYPAL_CLIENT_SECRET),
        environment=env)


def _subs():
    return _client().subscriptions


def _call(fn, *args) -> dict:
    try:
        resp = fn(*args)
    except ApiException as e:
        raise PayPalError(e.response_code or 502, str(e.response.text if e.response else e)) from e
    # Read PayPal's raw JSON: the SDK's typed models are used to build and send requests, but
    # re-serialising responses through them fails on fields PayPal returns as null.
    try:
        out = json.loads(resp.text) if resp.text else {}
    except ValueError:
        out = APIHelper.to_dictionary(resp.body) if resp.body is not None else {}
    if not isinstance(out, dict):
        out = {"body": out}
    out["http_status"] = resp.status_code
    return out


def approve_url(resource: dict) -> str | None:
    return next((link.get("href") for link in resource.get("links") or []
                 if link.get("rel") == "approve"), None)


# ---- plans --------------------------------------------------------------------

def plan_model(payload: dict) -> PlanRequest:
    """Build the SDK model, keeping falsy values the SDK parser drops.

    `BillingCycle.from_dictionary` treats `total_cycles: 0` ("bill forever") as missing, and
    PayPal then defaults to 1 cycle, so every subscription would expire after its first payment.
    Found while verifying against the sandbox; we set the value back on the model explicitly.
    """
    model = PlanRequest.from_dictionary(payload)
    for cyc, raw in zip(model.billing_cycles or [], payload.get("billing_cycles", [])):
        cyc.total_cycles = raw.get("total_cycles", 1)
        cyc.sequence = raw["sequence"]
    return model


def create_plan(payload: dict) -> dict:
    return _call(_subs().create_billing_plan, {
        "body": plan_model(payload), "prefer": "return=representation",
        "paypal_request_id": str(uuid.uuid4())})


def deactivate_plan(plan_id: str) -> dict:
    return _call(_subs().deactivate_billing_plan, plan_id)


def update_pricing_schemes(plan_id: str, body: dict) -> dict:
    return _call(_subs().update_billing_plan_pricing_schemes, {
        "id": plan_id, "body": UpdatePricingSchemesRequest.from_dictionary(body)})


# ---- subscriptions ------------------------------------------------------------

def create_subscription(body: dict) -> dict:
    return _call(_subs().create_subscription, {
        "body": CreateSubscriptionRequest.from_dictionary(body), "prefer": "return=representation",
        "paypal_request_id": str(uuid.uuid4())})


def get_subscription(sub_id: str) -> dict:
    return _call(_subs().get_subscription, {"id": sub_id})


def revise(sub_id: str, body: dict) -> dict:
    return _call(_subs().revise_subscription, {
        "id": sub_id, "body": ModifySubscriptionRequest.from_dictionary(body)})


def suspend(sub_id: str, reason: str) -> dict:
    return _call(_subs().suspend_subscription, {
        "id": sub_id, "body": SuspendSubscription(reason=reason[:128])})


def activate(sub_id: str, reason: str) -> dict:
    return _call(_subs().activate_subscription, {
        "id": sub_id, "body": ActivateSubscriptionRequest(reason=reason[:128])})


def cancel(sub_id: str, reason: str) -> dict:
    return _call(_subs().cancel_subscription, {
        "id": sub_id, "body": CancelSubscriptionRequest(reason=reason[:128])})


# ---- executor for audit-logged requests -------------------------------------------

_ROUTES = [
    (r"^/v1/billing/subscriptions/([^/]+)/revise$", lambda m, b: revise(m[1], b)),
    (r"^/v1/billing/subscriptions/([^/]+)/suspend$", lambda m, b: suspend(m[1], b.get("reason", ""))),
    (r"^/v1/billing/subscriptions/([^/]+)/activate$", lambda m, b: activate(m[1], b.get("reason", ""))),
    (r"^/v1/billing/subscriptions/([^/]+)/cancel$", lambda m, b: cancel(m[1], b.get("reason", ""))),
    (r"^/v1/billing/plans/([^/]+)/deactivate$", lambda m, b: deactivate_plan(m[1])),
    (r"^/v1/billing/plans/([^/]+)/update-pricing-schemes$",
     lambda m, b: update_pricing_schemes(m[1], b)),
]


def execute(request: dict) -> dict:
    """Run one logged request for real. Placeholder ids (never published to PayPal) are skipped."""
    path, body = request.get("path", ""), request.get("body") or {}
    if request.get("method") == "INTERNAL":
        return {"status": "executed", "internal": True}
    if request.get("simulated") or "PLAN_ID_" in json.dumps(request):
        return {"status": "dry_run", "reason": "simulated subscriber or unpublished plan; not sent to PayPal"}
    for pattern, fn in _ROUTES:
        m = re.match(pattern, path)
        if m:
            res = fn(m, body)
            url = approve_url(res)
            return {"status": "awaiting_buyer_approval" if url else "executed",
                    "approve_url": url, "response": res}
    return {"status": "failed", "error": f"no SDK route for {path}"}
